+	/* HWS X4 HDMI family. */
+	MAKE_ENTRY(0x8888, 0x8504, 0x8888, 0x0007, NULL),
+	/* HWS X4 SDI family. */
+	MAKE_ENTRY(0x8888, 0x6504, 0x8888, 0x0007, NULL),
